mapper.select:
select distinct bbf.BOOKSET_ID booksetId, bbf.SUBJECT_NO subjectNo, rpi.PROD_NAME prodName, bbf.O_CCY oCcy, bbf.TDY_O_D_AMT tdyODAmt, bbf.STATUS status, bbf.DATE_START dateStart, bbf.DATE_END dateEnd, bbf.ERRORMSG errormsg, bbf.UPDATE_TIME updateTime, bbf.UPDATE_USER updateUser from BOK_BALANCE_FSE bbf left join V_REP_PROD_INFO rpi on bbf.BOOKSET_ID = rpi.PROD_ID
1=1
AND bbf.BOOKSET_ID in
#{item}
AND bbf.SUBJECT_NO =#{subjectNo}
AND bbf.STATUS=#{status}
AND DATE_START >= TO_DATE(#{dateStart},'YYYY-MM-DD')
AND DATE_START <= TO_DATE(#{dateEnd},'YYYY-MM-DD')
OR DATE_END >= TO_DATE(#{dateStart},'YYYY-MM-DD')
AND DATE_END <= TO_DATE(#{dateEnd},'YYYY-MM-DD')
AND bbf.BOOKSET_ID in
#{item}
AND bbf.SUBJECT_NO =#{subjectNo}
AND bbf.STATUS=#{status}
and bbf.TDY_O_D_AMT is not null and bbf.TDY_O_D_AMT!=0
union all select distinct bbfh.BOOKSET_ID booksetId, bbfh.SUBJECT_NO subjectNo, rpi.PROD_NAME prodName, bbfh.O_CCY oCcy, bbfh.TDY_O_D_AMT tdyODAmt, bbfh.STATUS status, bbfh.DATE_START dateStart, bbfh.DATE_END dateEnd, bbfh.ERRORMSG errormsg, bbfh.UPDATE_TIME updateTime, bbfh.UPDATE_USER updateUser from BOK_BALANCE_FSE_HIS bbfh left join V_REP_PROD_INFO rpi on bbfh.BOOKSET_ID = rpi.PROD_ID
bbfh.TDY_O_D_AMT is not null and bbfh.TDY_O_D_AMT!=0
AND bbfh.BOOKSET_ID in
#{item}
AND bbfh.SUBJECT_NO =#{subjectNo}
AND bbfh.STATUS=#{status}
AND bbfh.DATE_START >= TO_DATE(#{dateStart},'YYYY-MM-DD')
AND bbfh.DATE_START <= TO_DATE(#{dateEnd},'YYYY-MM-DD')
OR bbfh.DATE_END >= TO_DATE(#{dateStart},'YYYY-MM-DD')
AND bbfh.DATE_END <= TO_DATE(#{dateEnd},'YYYY-MM-DD')
AND bbfh.BOOKSET_ID in
#{item}
AND bbfh.SUBJECT_NO =#{subjectNo}
AND bbfh.STATUS=#{status}
and bbfh.TDY_O_D_AMT is not null and bbfh.TDY_O_D_AMT!=0
order by updateTime desc

mapper.delete:
delete from BOK_BALANCE_FSE
where BOOKSET_ID = #{booksetId,jdbcType=VARCHAR} and
DATE_START = #{dateStart,jdbcType=DATE}
and DATE_END = #{dateEnd,jdbcType=DATE}
and SUBJECT_NO = #{subjectNo,jdbcType=VARCHAR}

